const ZONES=['UTC','America/New_York','Europe/Berlin','Asia/Kathmandu','Australia/Lord_Howe'];
const cmp=(a,b)=>a<b?-1:a>b?1:0;
function partsAt(ms,zone){const p=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(ms);const o={};for(const x of p)if(x.type!=='literal')o[x.type]=x.value;return `${o.year}-${o.month}-${o.day}T${o.hour}:${o.minute}`;}
function resolve(local,zone,fold){const [y,mo,d,h,mi]=local.match(/\d+/g).map(Number),naive=Date.UTC(y,mo-1,d,h,mi),found=[];for(let t=naive-15*3600000;t<=naive+15*3600000;t+=60000)if(partsAt(t,zone)===local)found.push(t);if(!found.length)return [];if(found.length===1)return found;return fold==='earlier'?[found[0]]:fold==='later'?[found.at(-1)]:found;}
const overlap=(a,b,c,d)=>a<d&&c<b;
export function book({range_start,range_end,rooms,transitions,meetings,blocks}){
 const rs=Date.parse(range_start), re=Date.parse(range_end), roomSet=new Set(rooms), byId=new Map(meetings.map(m=>[m.id,m]));
 const options=meetings.map(m=>{if(!ZONES.includes(m.zone))return [];return resolve(m.local_start,m.zone,m.fold).map(s=>({m,s,e:s+m.minutes*60000})).filter(o=>o.s>=rs&&o.e<=re).flatMap(o=>m.eligible_rooms.filter(r=>roomSet.has(r)).map(r=>({...o,r}))).filter(o=>!blocks.some(b=>b.room_id===o.r&&overlap(o.s,o.e,Date.parse(b.start),Date.parse(b.end))));});
 const order=meetings.map((m,i)=>i).sort((i,j)=>options[i].length-options[j].length||cmp(meetings[i].id,meetings[j].id));let best=null,chosen=[];
 function feasible(o){for(const x of chosen){if(x.m.id===o.m.id)return false;if(x.r===o.r&&overlap(x.s,x.e,o.s,o.e))return false;if(x.m.people.some(p=>o.m.people.includes(p))){let prev=x, next=o;if(o.s<x.s){prev=o;next=x;}const gap=transitions[prev.r][next.r];if(next.s<prev.e+gap)return false;}}
 for(const req of o.m.requires){const x=chosen.find(z=>z.m.id===req);if(!x||x.e>o.s)return false;}for(const x of chosen)if(x.m.requires.includes(o.m.id)&&o.e>x.s)return false;return true;}
 function score(){const value=chosen.reduce((a,x)=>a+x.m.value,0), count=chosen.length;const bookings=chosen.map(x=>({meeting_id:x.m.id,room_id:x.r,start:new Date(x.s).toISOString(),end:new Date(x.e).toISOString()})).sort((a,b)=>cmp(a.meeting_id,b.meeting_id));return {value,count,bookings};}
 function better(a,b){if(!b||a.value!==b.value)return !b||a.value>b.value;if(a.count!==b.count)return a.count>b.count;for(let i=0;i<a.bookings.length;i++)for(const k of ['meeting_id','room_id','start','end']){const c=cmp(a.bookings[i][k],b.bookings[i][k]);if(c)return c<0;}return false;}
 function dfs(k){if(k===order.length){const s=score();if(better(s,best))best=s;return;}const i=order[k],m=meetings[i];dfs(k+1);for(const o of options[i])if(feasible(o)){chosen.push(o);dfs(k+1);chosen.pop();}}
 dfs(0);return best||{value:0,count:0,bookings:[]};
}

